(86, 219, 39, '<p>Buen día chicos, comparto la información de las rino monedas de está semana. </p><p>Los que están en amarillo son los de la semana pasada, hubo uno que quedó pendiente por su clave, pero ya está confirmada. </p><p>Quedo atenta a cualquier cosa, gracias!</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 18:39:57'),
(89, 219, 2, '<p>Hola Yessenia, recibido lo trabajamos.  👍​</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 20:44:59'),
(90, 282, 5, '<p>Figma: https://www.figma.com/design/lCRiW8mVfM3pX3qJroeTwy/Resultados---Nuevas-compa%C3%B1ias?node-id=72-815&amp;t=GbzokQvfVQ83T2cC-0</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 20:52:06'),
(91, 286, 22, '<p>DEBERA CONTENER:</p><p>☐ Convocatoria</p><p>☐ Insumos</p><p>☐ Ubicacion (espacio asignado)</p><p>☐ Conexion remota (que todos los involucrados cuenten con la liga correspondiente)</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 22:41:29'),
(92, 287, 22, '<p>LA MINUTA DEBERA CONTENER:</p><p>☐ Debera ser compartida con todos los involucrados inclusive personal que no estaba convocada a la reunion, pero se involucra en los puntos que se tomaron en la reunion.</p><p>☐ Acuerdos</p><p>☐ Compromisos</p><p>☐ Estipulacion de fechas </p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 22:43:57'),
(93, 286, 22, '<p>☐ MATERIAL A PRESENTAR </p><p>☐ OBJETIVOS DE LA REUNION </p><p>☐ SEGUIMEINTO A LA BITACORA ANTERIOR</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 23:07:08'),
(94, 294, 2, '<p>asdfsadfsdafsad😛</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-17 23:43:47'),
(95, 342, 49, '<p>Hoy 18 de sep enviara su analisis de necesidades</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-18 17:14:27'),
(96, 336, 11, '<p>Se requiere que la IA nos diga la frecuencia de pago, por ejemplo mensual, anual, trimestral, semestral,</p><p>para poder calcular el valor bic de manera 100% automatizada</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-18 17:34:16'),
(97, 336, 11, '<p>Hay ciertos detalles en la IA</p><p>☐ La IA tiene que reconocer la frecuencia de pago</p><p>☐ La IA se confunde con con la prima pagada, hay casos en que selecciona la prima neta total, en ves de la prima neta</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-18 17:42:08'),
(98, 284, 11, '<p>☐ Agregar el nuevo campo tipoMoneda en el script de update-pphm-crudo-by-adm</p><p><br></p>', 'comment', NULL, NULL, NULL, 0, '2025-09-18 18:06:42'),
