(101, 284, 11, '<p>Se nesecita reprocesar todas las polizas en pphmCrudo para agregar el tipoMoneda, pero es nesesario que primero procesemos ediwin para asegurarnos de que no nos falten recibos</p><p>☐ Reprocesar ediwin</p><p>☐ Reprocesar opphmCrudo</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-18 18:16:14'),
