(103, 1229, 30, '<p>Pendiente el desarrollo complementario del proceso de Nomina, ya que se cuenta con un parámetro general, se integra Viernes antes de las 16:00</p>', 'comment', NULL, NULL, NULL, 0, '2025-09-19 18:48:20'),
