(3933, 1228, 11, 'commented', 'subtask_comment', NULL, '<p>Se requiere que la IA nos diga la frecuencia de pago, por ejemplo mensual, anual, trimestral, semestral,</p><p>para poder calcular el valor bic de manera 100% automatizada</p>', NULL, 'Comentario agregado en subtarea: Automatizacion dataIA en pegasoCrudo', '2025-09-18 17:34:16'),
(3934, 1367, 11, 'commented', 'comment', NULL, '<p>☐ Hay que agregar que se puedan eliminar las tareas creadas por el propietario de la tarea, ejemplo: si yo creo una tarea poder eliminar esa tarea</p>', NULL, 'Comentario agregado', '2025-09-18 17:38:25'),
